import re

def parse_kv_pairs(text: str) -> dict[str, str]:
    """
    Parses a string containing key-value pairs separated by '=' and splits them into a dictionary.
    Handles quoted values and ignores empty pairs or malformed entries.

    Example:
    >>> parse_kv_pairs('key1=value1 "key 2"=value2 key3="value with spaces"')
    {'key1': 'value1', 'key 2': 'value2', 'key3': 'value with spaces'}
    """
    pattern = r'([^=\s]+)\s*=\s*(?:(?P<quoted>"(?:\\"|[^"])*")|(?P<unquoted>[^"\s]+))'
    matches = re.finditer(pattern, text)
    result = {}

    for match in matches:
        key = match.group(1).strip()
        if match.group('quoted'):
            value = match.group('quoted')[1:-1].replace('\\"', '"')
        else:
            value = match.group('unquoted').strip()
        if key and value:
            result[key] = value

    return result
