    while n != 0:
        n, remainder = divmod(n, 3)
        if remainder == 2:
            remainder = -1
            n += 1
        digits.append('+' if remainder == 1 else '-' if remainder == -1 else '0')

    return ''.join(reversed(digits)) if digits else "0"
