def count_inversions(nums: list[int]) -> int:
    def merge_sort_and_count(nums, left, right):
        if left >= right:
            return 0

        mid = (left + right) // 2
        inv_count = merge_sort_and_count(nums, left, mid) + merge_sort_and_count(nums, mid + 1, right)

        i = left
        j = mid + 1
        k = left
        temp = [0] * (right - left + 1)

        while i <= mid and j <= right:
            if nums[i] <= nums[j]:
                temp[k - left] = nums[i]
                i += 1
            else:
                temp[k - left] = nums[j]
                inv_count += (mid - i + 1)
                j += 1
            k += 1

        while i <= mid:
            temp[k - left] = nums[i]
            i += 1
            k += 1

        while j <= right:
            temp[k - left] = nums[j]
            j += 1
            k += 1

        for idx in range(left, right + 1):
            nums[idx] = temp[idx - left]

        return inv_count

    return merge_sort_and_count(nums, 0, len(nums) - 1)
