def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    from functools import lru_cache

    n = len(coins)
    @lru_cache(maxsize=None)
    def dp(remaining: int, index: int) -> int:
        if remaining == 0:
            return 0
        if index == n:
            return float('inf')
        min_coins = float('inf')
        for count in range(0, limits[index] + 1):
            if coins[index] * count > remaining:
                break
            res = dp(remaining - coins[index] * count, index + 1)
            if res != float('inf'):
                min_coins = min(min_coins, res + count)
        return min_coins if min_coins != float('inf') else float('inf')

    result = dp(target, 0)
    return result if result != float('inf') else -1
