def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    from functools import lru_cache

    n = len(coins)
    if target == 0:
        return 0

    @lru_cache(maxsize=None)
    def dp(remaining, index):
        if remaining == 0:
            return 0
        if index >= n or remaining < 0:
            return float('inf')

        # Option 1: Don't use any coin of current type
        res = dp(remaining, index + 1)

        # Option 2: Use up to limit coins of current type
        for k in range(1, limits[index] + 1):
            current_coin = coins[index] * k
            if current_coin > remaining:
                break
            res = min(res, 1 + dp(remaining - current_coin, index + 1))

        return res

    result = dp(target, 0)
    return result if result != float('inf') else -1
