import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    source = source.replace('\n', ' ').replace('\t', ' ')
    tokens = []
    i = 0
    n = len(source)

    while i < n:
        if source[i].isspace():
            i += 1
            continue

        # Check for NUMBER
        if source[i].isdigit() or (source[i] == '.' and i + 1 < n and source[i+1].isdigit()):
            j = i
            if source[j] == '.':
                j += 1
                if not source[j].isdigit():
                    raise ValueError("Invalid number format")
            while j < n and (source[j].isdigit() or source[j] == '.'):
                if source[j] == '.' and j + 1 < n and source[j+1].isdigit():
                    j += 1
                else:
                    break
            if j > i and (source[j-1] == '.' and (j == i+1 or not source[j-2].isdigit())):
                raise ValueError("Invalid number format")
            tokens.append(("NUMBER", source[i:j]))
            i = j
            continue

        # Check for NAME
        if source[i].isalpha() or source[i] == '_':
            j = i
            while j < n and (source[j].isalnum() or source[j] == '_'):
                j += 1
            tokens.append(("NAME", source[i:j]))
            i = j
            continue

        # Check for OP
        if i + 1 < n:
            op2 = source[i:i+2]
            if op2 in {'==', '!=', '<=', '>='}:
                tokens.append(("OP", op2))
                i += 2
                continue

        if source[i] in {'+', '-', '*', '/', '<', '>', '=', '(', ')', ','}:
            tokens.append(("OP", source[i]))
            i += 1
            continue

        raise ValueError("Invalid character in source")

    return tokens
