def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0  # program counter
    executed = 0

    while pc < len(program) and executed < 1000:
        instruction = program[pc].split()
        cmd = instruction[0]

        if cmd == "PUSH":
            if len(instruction) != 2:
                raise ValueError(f"Invalid PUSH instruction: {program[pc]}")
            n = int(instruction[1])
            stack.append(n)

        elif cmd == "POP":
            if not stack:
                raise ValueError("POP from empty stack")
            stack.pop()

        elif cmd == "DUP":
            if not stack:
                raise ValueError("DUP from empty stack")
            stack.append(stack[-1])

        elif cmd == "SWAP":
            if len(stack) < 2:
                raise ValueError("SWAP needs at least two values")
            stack[-1], stack[-2] = stack[-2], stack[-1]

        elif cmd == "ADD":
            if len(stack) < 2:
                raise ValueError("ADD needs at least two values")
            a = stack.pop()
            b = stack.pop()
            stack.append(b + a)

        elif cmd == "SUB":
            if len(stack) < 2:
                raise ValueError("SUB needs at least two values")
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)

        elif cmd == "MUL":
            if len(stack) < 2:
                raise ValueError("MUL needs at least two values")
            a = stack.pop()
            b = stack.pop()
            stack.append(b * a)

        elif cmd == "JMP":
            if len(instruction) != 2:
                raise ValueError(f"Invalid JMP instruction: {program[pc]}")
            t = int(instruction[1])
            pc = t - 1  # pc will be incremented at the end

        elif cmd == "JZ":
            if len(instruction) != 2 or not stack:
                raise ValueError(f"Invalid JZ instruction: {program[pc]}")
            t = int(instruction[1])
            if stack[-1] == 0:
                pc = t - 1
            stack.pop()

        elif cmd == "HALT":
            break

        else:
            raise ValueError(f"Unknown instruction: {program[pc]}")

        pc += 1
        executed += 1

    if executed >= 1000:
        raise RuntimeError("More than 1000 instructions executed")

    return stack
