import math
from functools import reduce

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    congruences = [(r % m, m) for r, m in congruences]
    a1, m1 = congruences[0]

    for r, m in congruences[1:]:
        if m1 == 0:
            return None

        g, x, y = extended_gcd(m1, m)
        if (r - a1) % g != 0:
            return None

        lcm = m1 // g * m
        x0 = (a1 + (r - a1) // g * x % (m // g) * m1) % lcm
        a1, m1 = x0, lcm

    return (a1, m1)

def extended_gcd(a: int, b: int) -> tuple[int, int, int]:
    if a == 0:
        return (b, 0, 1)
    else:
        g, y, x = extended_gcd(b % a, a)
        return (g, x - (b // a) * y, y)
