from collections import deque

def min_slides(grid: list[str]) -> int:
    rows = len(grid)
    if rows == 0:
        return -1
    cols = len(grid[0])

    # Find start and end positions
    start = end = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS setup
    queue = deque()
    queue.append((start[0], start[1], 0))
    visited = set()
    visited.add((start[0], start[1]))

    while queue:
        x, y, steps = queue.popleft()

        if (x, y) == end:
            return steps

        for dx, dy in directions:
            nx, ny = x, y
            # Slide in the direction until wall or boundary
            while True:
                next_x = nx + dx
                next_y = ny + dy
                if 0 <= next_x < rows and 0 <= next_y < cols and grid[next_x][next_y] != '#':
                    nx, ny = next_x, next_y
                else:
                    break

            # Check if the slide was valid (i.e., moved at least one cell)
            if (nx, ny) != (x, y) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, steps + 1))

    return -1
