import re

def expand_template(template: str, values: dict[str, str]) -> str:
    def replacer(match):
        key = match.group(1)
        return values.get(key, match.group(0))

    # Handle escaped braces first: {{ and }}
    template = template.replace('{{', '\x00{').replace('}}', '}\x00')
    # Then process placeholders: {key}
    template = re.sub(r'\{([^}]+)\}', replacer, template)
    # Finally, restore escaped braces
    template = template.replace('\x00{', '{').replace('}\x00', '}')
    return template
