import re

def tidy_punctuation(text: str) -> str:
    # Step 1: Replace runs of whitespace with a single space and strip leading/trailing spaces
    text = re.sub(r'\s+', ' ', text).strip()

    # Step 2: Remove space before punctuation (.,;:!?)
    text = re.sub(r'\s+([,.;:!?])', r'\1', text)

    # Step 3: Add space after punctuation followed by a letter
    text = re.sub(r'([,.;:!?])([a-zA-Z])', r'\1 \2', text)

    # Step 4: Capitalize first letter and after .!? followed by space
    words = text.split(' ')
    if words:
        words[0] = words[0][0].upper() + words[0][1:] if words[0] else words[0]
        for i in range(1, len(words)):
            if words[i-1] in {'.', '!', '?'}:
                words[i] = words[i][0].upper() + words[i][1:] if words[i] else words[i]

    return ' '.join(words)

