def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end or min_len <= 0:
        return []

    # Filter and sort busy intervals
    busy_intervals = [interval for interval in busy if interval[0] < interval[1]]
    busy_intervals.sort()

    # Merge overlapping or touching intervals
    merged = []
    for start, end in busy_intervals:
        if not merged:
            merged.append([start, end])
        else:
            last_start, last_end = merged[-1]
            if start <= last_end:
                merged[-1][1] = max(last_end, end)
            else:
                merged.append([start, end])

    # Find free slots within the day
    free_slots = []
    current_start = day_start

    for start, end in merged:
        if start > current_start:
            gap_length = start - current_start
            if gap_length >= min_len:
                free_slots.append((current_start, start))
        current_start = max(current_start, end)

    # Check the remaining part after the last busy interval
    if current_start < day_end:
        gap_length = day_end - current_start
        if gap_length >= min_len:
            free_slots.append((current_start, day_end))

    return free_slots
