def identifier_to_snake(name: str) -> str:
    if not re.search(r'[a-zA-Z0-9]', name):
        return ""

    # Split by underscores or hyphens and handle camelCase/PascalCase
    parts = re.split(r'([A-Z][a-z]+|[A-Z]+?|[0-9]+|[a-z]+)', name)
    parts = [p for p in parts if p and p not in {'_', '-'}]

    # Process camelCase/PascalCase splits
    processed_parts = []
    for part in parts:
        if part.isupper():
            processed_parts.append(part.lower())
        elif part.isdigit():
            processed_parts.append(part)
        else:
            processed_parts.append(part)

    # Handle internal camelCase splits (e.g., 'XMLHttpRequest' -> 'xml_http_request')
    camel_split = re.split(r'(?<=[a-z])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])|(?<=[A-Za-z])(?=[0-9])|(?<=[0-9])(?=[A-Za-z])', name)
