def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    if not jobs:
        return []

    # Sort jobs by earliest deadline first
    jobs_sorted = sorted(jobs, key=lambda x: x[1])

    scheduled = []
    remaining_time = jobs_sorted[-1][1]  # Latest deadline

    for job in jobs_sorted:
        job_name, deadline, duration = job
        if remaining_time >= duration:
            scheduled.append(job_name)
            remaining_time -= duration

    return scheduled

