from collections import defaultdict

def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    teams = defaultdict(lambda: {'points': 0, 'goals_scored': 0, 'goals_conceded': 0})

    for home, away, hg, ag in results:
        teams[home]['goals_scored'] += hg
        teams[home]['goals_conceded'] += ag
        teams[away]['goals_scored'] += ag
        teams[away]['goals_conceded'] += hg

        if hg > ag:
            teams[home]['points'] += 3
        elif hg == ag:
            teams[home]['points'] += 1
            teams[away]['points'] += 1
        else:
            teams[away]['points'] += 3

    league = [
        (team, data['points'], data['goals_scored'] - data['goals_conceded'], data['goals_scored'])
        for team, data in teams.items()
    ]

    league.sort(key=lambda x: (-x[1], -(x[2]), -x[3], x[0]))
    return league
