def seating_arrangements(guests: list[str], conflicts: list[tuple[str, str]]) -> list[list[str]]:
    conflict_set = {(a, b) for a, b in conflicts}
    conflict_set.update({(b, a) for a, b in conflicts})
    valid_guests = [g for g in guests if g in conflict_set or any(g in pair for pair in conflict_set)]

    def is_valid(arrangement):
        for i in range(len(arrangement) - 1):
            if (arrangement[i], arrangement[i+1]) in conflict_set:
                return False
        return True

    unique_perms = set(permutations(guests))
    result = [list(p) for p in unique_perms if is_valid(p)]
    result.sort()
    return result
