    conflict_set = {(a, b) for a, b in conflicts if a in guests and b in guests}
    conflict_set.update({(b, a) for a, b in conflict_set})

    valid_arrangements = []
    for perm in permutations(guests):
        is_valid = True
        for i in range(len(perm) - 1):
            if (perm[i], perm[i+1]) in conflict_set:
                is_valid = False
                break
        if is_valid:
            valid_arrangements.append(list(perm))

    return sorted(valid_arrangements)
