def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    blocked_set = {(r, c) for r, c in blocked if 0 <= r < n and 0 <= c < n}
    count = 0

    def backtrack(row, cols, diag1, diag2):
        nonlocal count
        if row == n:
            count += 1
            return
        for col in range(n):
            if (row, col) in blocked_set:
                continue
            d1 = row - col
            d2 = row + col
            if col in cols or d1 in diag1 or d2 in diag2:
                continue
            backtrack(row + 1, cols | {col}, diag1 | {d1}, diag2 | {d2})

    backtrack(0, set(), set(), set())
    return count
```

