def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    frozen = set()
    failed = []
    new_balances = balances.copy()

    for i, op in enumerate(ops):
        if len(op) < 2 or op[0] not in {'deposit', 'withdraw', 'transfer', 'freeze', 'unfreeze'}:
            failed.append(i)
            continue

        if op[0] == 'freeze':
            if len(op) != 2:
                failed.append(i)
                continue
            account = op[1]
            if account not in new_balances:
                failed.append(i)
            else:
                frozen.add(account)

        elif op[0] == 'unfreeze':
            if len(op) != 2:
                failed.append(i)
                continue
            account = op[1]
            if account not in new_balances:
                failed.append(i)
            else:
                frozen.discard(account)

        elif op[0] in {'deposit', 'withdraw'}:
            if len(op) != 3:
                failed.append(i)
                continue
            account, amount = op[1], op[2]
            if (account not in new_balances or
                amount <= 0 or
                account in frozen):
                failed.append(i)
                continue

            if op[0] == 'deposit':
                new_balances[account] += amount
            else:
                if new_balances[account] - amount < 0:
                    failed.append(i)
                else:
                    new_balances[account] -= amount

        elif op[0] == 'transfer':
            if len(op) != 4:
                failed.append(i)
                continue
            source, target, amount = op[1], op[2], op[3]
            if (source not in new_balances or
                target not in new_balances or
                amount <= 0 or
                source in frozen or
                target in frozen or
                source == target):
                failed.append(i)
                continue

            if new_balances[source] - amount - 2 < 0:
                failed.append(i)
            else:
                new_balances[source] -= amount + 2
                new_balances[target] += amount

    return (new_balances, sorted(failed))
