def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = defaultdict(int)
    waiting = defaultdict(deque)
    waiting_order = []
    output_waiting = []

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] += quantity
            # Process waiting orders for this item
            while waiting[item] and stock[item] >= waiting[item][0][1]:
                ordered_item, ordered_qty = waiting[item].popleft()
                stock[item] -= ordered_qty
                waiting_order.append((ordered_item, ordered_qty))
        else:  # kind == 'order'
            if stock[item] >= quantity:
                stock[item] -= quantity
                waiting_order.append((item, quantity))
            else:
                waiting[item].append((item, quantity))

    # Prepare the output waiting list in order of occurrence
    output_waiting = []
    seen = set()
    for item, qty in waiting_order:
        if item not in seen:
            seen.add(item)
            for w_item, w_qty in waiting[item]:
                output_waiting.append((w_item, w_qty))
            waiting[item].clear()

    for item in waiting:
        for w_item, w_qty in waiting[item]:
            output_waiting.append((w_item, w_qty))

    return dict(stock), output_waiting

