def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    executed = 0
    max_executions = 1000

    while ip < len(program) and executed < max_executions:
        instruction = program[ip].split()
        executed += 1

        if not instruction:
            ip += 1
            continue

        cmd = instruction[0]

        if cmd == 'PUSH':
            n = int(instruction[1])
            stack.append(n)
            ip += 1

        elif cmd == 'POP':
            if not stack:
                return None
            stack.pop()
            ip += 1

        elif cmd == 'DUP':
            if not stack:
                return None
            stack.append(stack[-1])
            ip += 1

        elif cmd == 'SWAP':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
            ip += 1

        elif cmd == 'ADD':
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
            ip += 1

        elif cmd == 'SUB':
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
            ip += 1

        elif cmd == 'MUL':
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
            ip += 1

        elif cmd == 'JMP':
            t = int(instruction[1])
            ip = t

        elif cmd == 'JZ':
            if not stack:
                return None
            t = int(instruction[1])
            if stack[-1] == 0:
                ip = t
            else:
                ip += 1

        else:
            ip += 1

    if executed >= max_executions:
        return None
    return stack
