def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    pc = 0  # program counter
    steps = 0
    max_steps = 1000

    while pc < len(program) and steps < max_steps:
        instruction = program[pc].split()
        cmd = instruction[0]

        try:
            if cmd == 'PUSH':
                n = int(instruction[1])
                stack.append(n)
            elif cmd == 'POP':
                if len(stack) < 1:
                    return None
                stack.pop()
            elif cmd == 'DUP':
                if len(stack) < 1:
                    return None
                stack.append(stack[-1])
            elif cmd == 'SWAP':
                if len(stack) < 2:
                    return None
                a, b = stack.pop(), stack.pop()
                stack.append(a)
                stack.append(b)
            elif cmd == 'ADD':
                if len(stack) < 2:
                    return None
                b, a = stack.pop(), stack.pop()
                stack.append(a + b)
            elif cmd == 'SUB':
                if len(stack) < 2:
                    return None
                b, a = stack.pop(), stack.pop()
                stack.append(a - b)
            elif cmd == 'MUL':
                if len(stack) < 2:
                    return None
                b, a = stack.pop(), stack.pop()
                stack.append(a * b)
            elif cmd == 'JMP':
                t = int(instruction[1])
                pc = t - 1  # will increment by 1 after loop
            elif cmd == 'JZ':
                if len(stack) < 1:
                    return None
                t = int(instruction[1])
                if stack[-1] == 0:
                    pc = t - 1
        except (IndexError, ValueError):
            return None

        pc += 1
        steps += 1

    if steps >= max_steps:
        return None
    return stack[::-1] if stack else []
