    stack = []
    pc = 0
    steps = 0
    max_steps = 1000

    while pc < len(program) and steps < max_steps:
        instruction = program[pc].split()
        cmd = instruction[0]

        try:
            if cmd == 'PUSH':
                n = int(instruction[1])
                stack.append(n)
                pc += 1
            elif cmd == 'POP':
                if len(stack) < 1:
                    return None
                stack.pop()
                pc += 1
            elif cmd == 'DUP':
                if len(stack) < 1:
                    return None
                stack.append(stack[-1])
                pc += 1
            elif cmd == 'SWAP':
                if len(stack) < 2:
                    return None
                a, b = stack.pop(), stack.pop()
                stack.append(a)
                stack.append(b)
                pc += 1
            elif cmd == 'ADD':
                if len(stack) < 2:
                    return None
                b, a = stack.pop(), stack.pop()
                stack.append(a + b)
                pc += 1
            elif cmd == 'SUB':
                if len(stack) < 2:
                    return None
                b, a = stack.pop(), stack.pop()
                stack.append(a - b)
                pc += 1
            elif cmd == 'MUL':
                if len(stack) < 2:
                    return None
                b, a = stack.pop(), stack.pop()
                stack.append(a * b)
                pc += 1
            elif cmd == 'JMP':
                t = int(instruction[1])
                pc = t
            elif cmd == 'JZ':
                if len(stack) < 1:
                    return None
                t = int(instruction[1])
                if stack[-1] == 0:
                    pc = t
                else:
                    pc += 1
            else:
                return None
        except (IndexError, ValueError):
            return None

        steps += 1

    if steps >= max_steps:
        return None
    return stack[::-1]

