def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Invalid input")

    is_negative = False
    if number[0] == '-':
        is_negative = True
        number = number[1:]
    if not number:
        raise ValueError("Invalid input")

    try:
        decimal_value = int(number, from_base)
    except ValueError:
        raise ValueError("Invalid digit for the given base")

    if decimal_value == 0:
        return '0'

    digits = []
    while decimal_value > 0:
        remainder = decimal_value % to_base
        if remainder < 10:
            digits.append(str(remainder))
        else:
            digits.append(chr(ord('a') + remainder - 10))
        decimal_value = decimal_value // to_base

    result = ''.join(reversed(digits))
    return '-' + result if is_negative else result
