def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    pc = 0  # program counter
    max_instructions = 1000
    executed = 0

    while pc < len(program):
        if executed >= max_instructions:
            return None
        executed += 1
        instruction = program[pc].split()

        try:
            if instruction[0] == 'PUSH':
                stack.append(int(instruction[1]))

            elif instruction[0] == 'POP':
                if len(stack) < 1:
                    return None
                stack.pop()

            elif instruction[0] == 'DUP':
                if len(stack) < 1:
                    return None
                stack.append(stack[-1])

            elif instruction[0] == 'SWAP':
                if len(stack) < 2:
                    return None
                stack[-1], stack[-2] = stack[-2], stack[-1]

            elif instruction[0] in ('ADD', 'SUB', 'MUL'):
                if len(stack) < 2:
                    return None
                b = stack.pop()
                a = stack.pop()
                if instruction[0] == 'ADD':
                    stack.append(a + b)
                elif instruction[0] == 'SUB':
                    stack.append(a - b)
                elif instruction[0] == 'MUL':
                    stack.append(a * b)

            elif instruction[0] == 'JMP':
                t = int(instruction[1])
                if t < 0:
                    return None
                pc = t - 1  # pc will be incremented at the end

            elif instruction[0] == 'JZ':
                if len(stack) < 1:
                    return None
                t = int(instruction[1])
                if t < 0:
                    return None
                if stack[-1] == 0:
                    pc = t - 1  # pc will be incremented at the end
                    stack.pop()

            pc += 1
        except (IndexError, ValueError):
            return None

