from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Find S and E positions
    start = end = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS setup: (i, j, wall_break_used, steps)
    queue = deque()
    queue.append((start[0], start[1], False, 0))
    visited = {}
    visited[(start[0], start[1], False)] = True

    while queue:
        i, j, break_used, steps = queue.popleft()

        if (i, j) == end:
            return steps

        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < rows and 0 <= nj < cols:
                cell = grid[ni][nj]
                if cell == '#':
                    if not break_used:
                        queue.append((ni, nj, True, steps + 1))
                elif cell == '.' or cell == 'E':
                    if (ni, nj, break_used) not in visited:
                        visited[(ni, nj, break_used)] = True
                        queue.append((ni, nj, break_used, steps + 1))

    return -1
