from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start = end = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    def bfs(break_wall=None):
        visited = [[False for _ in range(cols)] for _ in range(rows)]
        queue = deque()
        queue.append((start[0], start[1], 0))
        visited[start[0]][start[1]] = True
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while queue:
            x, y, dist = queue.popleft()
            if (x, y) == end:
                return dist
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols:
                    if not visited[nx][ny]:
                        if grid[nx][ny] == '#':
                            if break_wall is None:
                                continue
                            if (nx, ny) != break_wall:
                                continue
                        visited[nx][ny] = True
                        queue.append((nx, ny, dist + 1))
        return -1

    min_dist = float('inf')
    walls = [(i, j) for i in range(rows) for j in range(cols) if grid[i][j] == '#']

    for wall in walls:
        dist = bfs(wall)
        if dist != -1 and dist < min_dist:
            min_dist = dist

    dist_without_break = bfs()
    if dist_without_break != -1 and dist_without_break < min_dist:
        min_dist = dist_without_break

    return min_dist if min_dist != float('inf') else -1
