from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS setup for initial path without breaking any wall
    queue = deque()
    queue.append((start[0], start[1], 0, False))  # (row, col, steps, wall_broken)
    visited = [[[False for _ in range(2)] for __ in range(cols)] for ___ in range(rows)]
    visited[start[0]][start[1]][0] = True

    while queue:
        x, y, steps, wall_broken = queue.popleft()

        if (x, y) == end:
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols:
                if grid[nx][ny] == '#':
                    if not wall_broken:
                        queue.append((nx, ny, steps + 1, True))
