from typing import List, Tuple, Optional

def shortest_path_one_break(grid: List[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    def bfs(start: Tuple[int, int], can_break: bool) -> int:
        queue = deque([(start[0], start[1], can_break)])
        visited = [[[False for _ in range(2)] for __ in range(cols)] for ___ in range(rows)]
        visited[start[0]][start[1]][can_break] = True
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        steps = 0

        while queue:
            for _ in range(len(queue)):
                x, y, break_used = queue.popleft()
                if (x, y) == end:
                    return steps
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < rows and 0 <= ny < cols:
                        if grid[nx][ny] == '#':
                            if break_used:
                                continue
                            if not visited[nx][ny][1]:
                                visited[nx][ny][1] = True
                                queue.append((nx, ny, True))
                        elif not visited[nx][ny][break_used]:
                            visited[nx][ny][break_used] = True
                            queue.append((nx, ny, break_used))
            steps += 1
        return -1

    return bfs(start, False)
