from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None

    # Find S and E positions
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS setup for shortest path without break
    queue = deque()
    queue.append((start[0], start[1], 0))
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    visited[start[0]][start[1]] = True
    shortest = [[-1 for _ in range(cols)] for _ in range(rows)]
    shortest[start[0]][start[1]] = 0

    # BFS to find shortest path without any break
    while queue:
        x, y, dist = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny] and grid[nx][ny] != '#':
                visited[nx][ny] = True
                shortest[nx][ny] = dist + 1
                queue.append((nx, ny, dist + 1))

    # If no path without break
    if shortest[end[0]][end[1]] == -1:
        return -1

    # BFS setup for shortest path with one break
    queue = deque()
    queue.append((start[0], start[1], 0, -1))  # x, y, dist, last_break_dist
    visited = [[[False for _ in range(2)] for _ in range(cols)] for _ in range(rows)]
    visited[start[0]][start[1]][0] = True
    min_dist = float('inf')

    while queue:
        x, y, dist, break_dist = queue.popleft()
        if x == end[0] and y == end[1]:
            if break_dist == -1:
                min_dist = min(min_dist, dist)
            else:
                min_dist = min(min_dist, dist + break_dist)
            continue

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols:
                if grid[nx][ny] == '#':
                    if break_dist == -1:
                        queue.append((nx, ny, dist + 1, 1))
                        visited[nx][ny][1] = True
                else:
                    if break_dist == -1 or not visited[nx][ny][break_dist]:
                        visited[nx][ny][break_dist] = True
                        queue.append((nx, ny, dist + 1, break_dist))

    return min_dist if min_dist != float('inf') else -1
