def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    rows = len(grid)
    cols = len(grid[0])
    changed = True

    # Create a deep copy of the grid to avoid modifying the original
    new_grid = [row.copy() for row in grid]

    while changed:
        changed = False
        topple_cells = []

        # Check each cell for toppling
        for r in range(rows):
            for c in range(cols):
                if new_grid[r][c] >= 4:
                    topple_cells.append((r, c))

        # Process toppling
        for r, c in topple_cells:
            new_grid[r][c] -= 4
            changed = True

            # Distribute grains to neighbors
            if r > 0:
                new_grid[r-1][c] += 1
            if r < rows - 1:
                new_grid[r+1][c] += 1
            if c > 0:
                new_grid[r][c-1] += 1
            if c < cols - 1:
                new_grid[r][c+1] += 1

    return new_grid
