import os
from pathlib import Path

def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    # Normalize and join paths safely
    try:
        path = Path(web_root).resolve()
        if not path.is_absolute():
            raise ValueError("web_root must be an absolute path")

        # Handle root case
        if request_path == "/":
            target_path = path / "index.html"
        else:
            # Split path into components and join safely
            components = [c for c in request_path.split('/') if c]
            target_path = path
            for component in components:
                target_path /= component

        # Security checks
        if not target_path.is_relative_to(path):
            return (404, b"Not Found")

        if not target_path.exists() or not target_path.is_file():
            return (404, b"Not Found")

        # Read file content
        with open(target_path, 'rb') as f:
            content = f.read()

        return (200, content)

    except (ValueError, OSError):
        return (404, b"Not Found")
