import yaml
from typing import Any, Dict

def parse_config(text: str) -> Dict[str, Any]:
    """
    Parse a YAML configuration string into a dictionary.

    Args:
        text: A string containing YAML configuration.

    Returns:
        A dictionary representing the parsed YAML document.
        Returns an empty dictionary if the document is empty.

    Raises:
        yaml.YAMLError: If the YAML is malformed or contains unsafe constructs.
        ValueError: If the top-level node is not a mapping or contains invalid keys.
    """
    if not text.strip():
        return {}

    try:
        # Safe loading with explicit allowed types and no custom constructors
        parsed = yaml.safe_load(text)
    except yaml.YAMLError as e:
        raise yaml.YAMLError(f"Invalid YAML: {str(e)}")

    if parsed is None:
        return {}

    if not isinstance(parsed, dict):
        raise ValueError("Top-level node must be a mapping (dictionary)")

    # Validate all keys are strings (YAML preserves key types, but we enforce string keys)
    for key in parsed.keys():
        if not isinstance(key, str):
            raise ValueError(f"All keys must be strings. Found: {type(key).__name__}")

    return parsed
