def restore_session(data: bytes) -> Dict[str, Union[int, str, List[Union[int, str]]]]:
    """
    Safely unpickles session data and validates its structure.

    Args:
        data: Pickled session data as bytes.

    Returns:
        A dictionary with string keys and values that are either int, str,
        or list of int/str.

    Raises:
        ValueError: If the data is invalid or malformed.
    """
    try:
        # Unpickle safely using a custom loader
        def safe_loads(s: bytes) -> Any:
            return pickle.loads(s, encoding='bytes', errors='strict')

        session_data = safe_loads(data)

        # Validate the structure recursively
        def validate_structure(obj: Any) -> None:
            if isinstance(obj, dict):
                for key, value in obj.items():
                    if not isinstance(key, str):
                        raise ValueError("Dictionary keys must be strings")
                    validate_structure(value)
            elif isinstance(obj, list):
                for item in obj:
                    validate_structure(item)
            elif not isinstance(obj, (int, str)):
                raise ValueError("Values must be int, str, or list of int/str")

        validate_structure(session_data)

        return session_data

    except (pickle.PickleError, ValueError, AttributeError, TypeError) as e:
        raise ValueError("Invalid session data: unable to restore session") from e
