from typing import Dict, Any

def restore_session(data: bytes) -> Dict[str, Any]:
    """
    Securely restores a session dictionary from pickled bytes.
    Only allows safe types (str, int, list) and validates structure.

    Args:
        data: Pickled session data as bytes.

    Returns:
        Restored session dictionary with string keys and allowed values.

    Raises:
        ValueError: If data is invalid or contains unsafe types.
        pickle.UnpicklingError: If unpickling fails.
    """
    # Security checks
    if not data:
        raise ValueError("Empty session data")

    # Custom unpickler with restricted allowed classes
    class SafeUnpickler(pickle.Unpickler):
        def find_class(self, module, name):
            if module == 'builtins':
                if name in ('str', 'int', 'list', 'tuple'):
                    return getattr(__builtins__, name)
            raise pickle.UnpicklingError(f"Unsafe class: {module}.{name}")

        def reduce(self, func, args):
            if func is list:
                return list, args
            if func is tuple:
                return tuple, args
            raise pickle.UnpicklingError(f"Unsafe function: {func}")

    try:
        # Use StringIO to handle potential file-like objects in pickle
        with io.BytesIO(data) as buf:
            unpickler = SafeUnpickler(buf)
            session = unpickler.load()
    except (pickle.UnpicklingError, AttributeError, ImportError) as e:
        raise ValueError(f"Invalid session data: {str(e)}")

    # Validate the structure
    if not isinstance(session, dict):
        raise ValueError("Session data must be a dictionary")

    for key, value in session.items():
        if not isinstance(key, str):
            raise ValueError(f"Session key must be string, got {type(key)}")

        if isinstance(value, (int, str)):
            continue
        elif isinstance(value, list):
            for item in value:
                if not isinstance(item, (int, str)):
                    raise ValueError(f"List items must be int or str, got {type(item)}")
        else:
            raise ValueError(f"Session value must be int, str, or list, got {type(value)}")

    return session
