        if not blob:
            raise ValueError("Empty blob provided")

        # Check for safe pickle protocol (we only allow protocol 4)
        if pickletools.proto_version(blob) != 4:
            raise ValueError("Unsupported pickle protocol version")

        # Check for zlib header (first 2 bytes should be 0x78, 0x9C)
        if len(blob) < 2 or blob[0] != 0x78 or blob[1] != 0x9C:
