        def check_depth(obj: Any, current_depth: int = 0, max_depth: int = 100) -> Any:
            if current_depth > max_depth:
                raise ValueError("Maximum depth exceeded")

            if isinstance(obj, dict):
                return {k: check_depth(v, current_depth + 1, max_depth)
                        for k, v in obj.items()}
            elif isinstance(obj, (list, tuple)):
                return [check_depth(v, current_depth + 1, max_depth) for v in obj]
            else:
                return obj

        # Decompress and unpickle with security checks
        decompressed = zlib.decompress(blob)
        entry = pickle.loads(decompressed, encoding='utf-8', errors='strict')

        # Validate the structure and types
        def validate_entry(obj: Any) -> None:
            if isinstance(obj, dict):
                for k, v in obj.items():
                    if not isinstance(k, str):
                        raise ValueError("Dictionary keys must be strings")
                    validate_entry(v)
            elif isinstance(obj, list):
