import re
import operator

def evaluate_expression(expression: str) -> float:
    # Remove all whitespace from the expression
    expr = expression.replace(" ", "")

    # Check for empty string
    if not expr:
        raise ValueError("Empty expression")

    # Check for balanced parentheses
    if expr.count('(') != expr.count(')'):
        raise ValueError("Unbalanced parentheses")

    # Validate tokens
    tokens = re.findall(r'(\d+\.?\d*|\.\d+|\+|\-|\*|\/|\*\*|\(|\))', expr)
    if not tokens:
        raise ValueError("Invalid expression")

    # Check for invalid tokens
    for token in tokens:
        if token not in ('+', '-', '*', '/', '**', '(', ')'):
            if not (token.replace('.', '', 1).isdigit() or (token.startswith('-') and token[1:].replace('.', '', 1).isdigit())):
                raise ValueError(f"Invalid token: {token}")

    # Convert infix to postfix notation (Reverse Polish Notation)
    precedence = {'**': 4, '*': 3, '/': 3, '+': 2, '-': 2}
    output = []
    operators = []

    i = 0
    while i < len(tokens):
        token = tokens[i]

        if token.replace('.', '', 1).isdigit() or (token.startswith('-') and token[1:].replace('.', '', 1).isdigit()):
            output.append(float(token))
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                output.append(operators.pop())
            if not operators:
                raise ValueError("Mismatched parentheses")
            operators.pop()  # Remove '('
        else:
            while (operators and operators[-1] != '(' and
                   precedence[operators[-1]] >= precedence[token]):
                output.append(operators.pop())
            operators.append(token)
        i += 1

    while operators:
        if operators[-1] == '(':
            raise ValueError("Mismatched parentheses")
        output.append(operators.pop())

    # Evaluate postfix expression
    stack = []
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '**': operator.pow
    }

    for token in output:
        if isinstance(token, float):
            stack.append(token)
        else:
            if len(stack) < 2:
                raise ValueError("Invalid expression")
            b = stack.pop()
            a = stack.pop()
            try:
                result = ops[token](a, b)
            except ZeroDivisionError:
                raise ZeroDivisionError("Division by zero")
            stack.append(result)

    if len(stack) != 1:
        raise ValueError("Invalid expression")

    return stack[0]
