            raise ValueError("Unbalanced parentheses")
        output.append(operators.pop())

    # Evaluate the postfix expression
    stack = []
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '**': operator.pow,
        'u-': lambda x: -x
    }

    for token in output:
        if isinstance(token, float):
            stack.append(token)
        else:
            if token == 'u-':
                if not stack:
                    raise ValueError("Invalid unary minus")
                a = stack.pop()
                stack.append(ops[token](a))
