import re
import operator
from numbers import Number

def evaluate_expression(expression: str) -> float:
    # Remove all whitespace from the expression
    expr = expression.replace(' ', '')

    # Check for empty expression
    if not expr:
        raise ValueError("Empty expression")

    # Check for balanced parentheses
    if expr.count('(') != expr.count(')'):
        raise ValueError("Unbalanced parentheses")

    # Validate characters
    if not re.fullmatch(r'^[\d+\-*/().\s]+$', expression):
        raise ValueError("Invalid characters in expression")

    # Replace unary minus with a special token
    expr = re.sub(r'(?<!\d|\))(\-)', 'u-', expr)

    # Tokenize the expression
    tokens = re.findall(r'(\d+\.?\d*|\.\d+|\+|\-|\*|/|\*\*|u-|\(|\))', expr)

    # Check for invalid tokens
    for token in tokens:
        if token not in ('+', '-', '*', '/', '**', 'u-', '(', ')'):
            raise ValueError(f"Invalid token: {token}")

    # Convert tokens to postfix notation (Reverse Polish Notation)
    output = []
    operators = []
    precedence = {'**': 4, 'u-': 4, '*': 3, '/': 3, '+': 2, '-': 2}

    for token in tokens:
        if token.replace('.', '').isdigit():
            output.append(float(token))
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                output.append(operators.pop())
            if not operators:
                raise ValueError("Mismatched parentheses")
            operators.pop()  # Remove the '('
        else:
            while (operators and operators[-1] != '(' and
                   precedence[operators[-1]] >= precedence[token]):
                output.append(operators.pop())
            operators.append(token)

    while operators:
        if operators[-1] == '(':
            raise ValueError("Mismatched parentheses")
        output.append(operators.pop())

    # Evaluate the postfix expression
    stack = []
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '**': operator.pow,
        'u-': lambda x: -x
    }

    for token in output:
        if isinstance(token, float):
            stack.append(token)
        else:
            if len(stack) < 2 and token != 'u-':
                raise ValueError("Invalid expression")
            if token == 'u-':
                if not stack:
                    raise ValueError("Invalid expression")
                a = stack.pop()
                stack.append(ops[token](a))
            else:
                b = stack.pop()
                a = stack.pop()
                try:
                    result = ops[token](a, b)
                except ZeroDivisionError:
                    raise ZeroDivisionError("division by zero")
                stack.append(result)

    if len(stack) != 1:
        raise ValueError("Invalid expression")

    return stack[0]
