    if re.search(r'[\+\-\*/\^]\s*[\+\-\*/\^]', formula):
        raise ValueError("Invalid formula: consecutive operators")
    if formula.startswith(('+', '-', '*', '/', '^')) and not formula.startswith('-'):
        raise ValueError("Invalid formula: operator at start")
    if formula.endswith(('+', '-', '*', '/', '^')):
        raise ValueError("Invalid formula: operator at end")

    # Check for division by zero
    if '/' in formula:
        try:
