import math
import re
from numbers import Number

def evaluate_formula(formula: str, x: float) -> float:
    # Validar que la fórmula solo contenga caracteres permitidos
    if not re.fullmatch(r'^[\d+\-*/().x\sabsincosqrt]+$', formula.replace(' ', '')):
        raise ValueError("Fórmula contiene caracteres no permitidos")

    # Reemplazar funciones matemáticas por sus equivalentes de math
    formula = formula.replace('sqrt', 'math.sqrt').replace('abs', 'math.abs').replace('sin', 'math.sin').replace('cos', 'math.cos')

    # Validar que no haya nombres no permitidos (usando regex para buscar palabras no válidas)
    if re.search(r'\b([a-zA-Z_]+(?!\b(x|abs|sin|cos|sqrt)\b))\b', formula):
        raise ValueError("Fórmula contiene nombres no permitidos")

    # Validar que los paréntesis estén balanceados
    if formula.count('(') != formula.count(')'):
        raise ValueError("Paréntesis no balanceados")

    # Validar que no haya operadores consecutivos o al inicio/fin (excepto menos unario)
    if re.search(r'([+\-*/**])([+\-*/**])|^([+\-*/**])|([+\-*/**])$', formula.replace(' ', '')):
        raise ValueError("Operadores mal colocados")

    # Validar que no haya dos puntos decimales consecutivos
    if '..' in formula.replace(' ', ''):
        raise ValueError("Números con más de un punto decimal")

    # Validar que no haya divisiones por cero (solo sintácticamente)
    if '/0' in formula.replace(' ', '') or '/(' in formula:
        raise ValueError("Posible división por cero")

    try:
        # Crear un namespace seguro con solo las funciones permitidas y la variable x
        namespace = {
            'x': x,
            'math': math,
            'sin': math.sin,
            'cos': math.cos,
            'sqrt': math.sqrt,
            'abs': math.fabs
        }

        # Evaluar la fórmula con el namespace seguro
        result = eval(formula, {'__builtins__': None}, namespace)

        # Validar que el resultado sea un número
        if not isinstance(result, Number):
            raise ValueError("Resultado no es un número")

        return float(result)

    except ZeroDivisionError:
        raise ZeroDivisionError("División por cero")
    except Exception:
        raise ValueError("Fórmula no válida")
