import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https:// (case-insensitive)
    if not re.match(r'^https://', url, re.IGNORECASE):
        return False

    # Check for invalid characters (backslash, space, or control characters)
    if re.search(r'[\\ \x00-\x1f\x7f]', url):
        return False

    # Extract host and port
    match = re.match(r'^https://([^/@]+)(?::(\d+))?(/|$)', url, re.IGNORECASE)
    if not match:
        return False

    host = match.group(1)
    port = match.group(2)

    # Check port (must be absent or 443)
    if port and int(port) != 443:
        return False

    # Check host is not localhost or ends with .localhost
    if re.match(r'^localhost$', host, re.IGNORECASE) or re.match(r'\.localhost$', host, re.IGNORECASE):
        return False

    # Check host is a valid DNS name
    if not re.match(r'^([a-z0-9-]+\.)+[a-z0-9-]+$', host, re.IGNORECASE):
        return False

    # Check each label in host (after removing trailing dot)
    host_clean = host.rstrip('.')
    labels = host_clean.split('.')
    if len(labels) < 2:
        return False

    for label in labels[:-1]:
        if not label or not re.match(r'^[a-z0-9-]+$', label, re.IGNORECASE):
            return False

    if not labels[-1] or not re.match(r'^[a-z]+$', labels[-1], re.IGNORECASE):
        return False

    return True
