import ipaddress
import re

def is_public_ip(ip_str: str) -> bool:
    # Check if the string is a valid IPv4 or IPv6 address in standard text form
    if not re.fullmatch(r'^(([0-9]{1,3}\.){3}[0-9]{1,3}|[a-fA-F0-9:]+(?:%[a-zA-Z0-9]+)?)$', ip_str):
        return False

    try:
        ip = ipaddress.ip_address(ip_str)
    except ValueError:
        return False

    # Check for IPv4-mapped IPv6 addresses (::ffff:a.b.c.d)
    if ip.version == 6 and ip.is_ipv4_mapped:
        ip = ipaddress.ip_address(ip_str.split(':')[-1])

    # Check if the IP is public
    if ip.is_private:
        return False
    if ip.is_loopback:
        return False
    if ip.is_link_local:
        return False
    if ip.is_multicast:
        return False
    if ip.is_reserved:
        return False
    if ip.is_unspecified:
        return False

    # Check for shared address space 100.64.0.0/10
    if ip.version == 4 and ipaddress.ip_address('100.64.0.0') <= ip <= ipaddress.ip_address('100.127.255.255'):
        return False

    # Check for IPv4 broadcast address
    if ip.version == 4 and ip == ipaddress.ip_address('255.255.255.255'):
        return False

    return True
