def log_requests(log_path: str, requests: list[dict]) -> int:
    import os
    from pathlib import Path

    def sanitize_string(s: str) -> str:
        # Escape double quotes and ensure UTF-8 compatibility
        return s.replace('"', '\\"').encode('utf-8', 'replace').decode('utf-8')

    lines = []
    for req in requests:
        try:
            timestamp = sanitize_string(str(req['timestamp']))
            ip = sanitize_string(str(req['ip']))
            path = sanitize_string(str(req['path']))
            user_agent = sanitize_string(str(req['user_agent']))

            line = f'{timestamp} {ip} "{path}" "{user_agent}"\n'
            lines.append(line)
        except KeyError as e:
            raise ValueError(f"Missing required key in request dict: {e}")

    if not lines:
        return 0

    # Use atomic write to prevent corruption
    temp_path = f"{log_path}.tmp"
    try:
        with open(temp_path, 'a', encoding='utf-8') as f:
            f.writelines(lines)

        # Atomic replace (works on Unix; for Windows, consider using shutil.move or similar)
        Path(log_path).touch(exist_ok=True)
        Path(temp_path).replace(log_path)
        return len(lines)
    except Exception as e:
        # Clean up temp file if something went wrong
        try:
            os.remove(temp_path)
        except:
            pass
        raise RuntimeError(f"Failed to write log file: {e}")
