from typing import Optional

def inflate_payload(data: bytes) -> bytes:
    """Decompress zlib-compressed data with security checks."""
    if not data:
        return b""

    try:
        # Check for zlib header (first 2 bytes should be 0x78, 0x9C)
        if len(data) < 2 or data[:2] != zlib.crc32(b"x")[:2].to_bytes(2, 'big'):
            raise ValueError("Invalid zlib header")

        # Check for maximum allowed size to prevent DoS via large compressed data
        max_decompressed_size = 1024 * 1024 * 100  # 100MB limit
        decompressed = zlib.decompress(data, max_length=max_decompressed_size)

        # Verify the decompressed data doesn't exceed our size limit
        if len(decompressed) > max_decompressed_size:
            raise ValueError("Decompressed data too large")

        return decompressed

    except zlib.error as e:
        raise ValueError(f"Invalid compressed data: {str(e)}")
    except Exception:
        raise ValueError("Decompression failed")
