def count_items(xml_text: str) -> int:
    try:
        # Parse the XML text safely
        root = ET.parse(StringIO(xml_text)).getroot()
    except ET.ParseError:
        # If parsing fails, try to find standalone <item> tags (malformed XML)
        count = 0
        i = 0
        while i < len(xml_text):
            if xml_text.startswith('<item', i):
                # Check if it's a proper opening tag
                j = xml_text.find('>', i)
                if j == -1:
                    break
                tag_content = xml_text[i:j]
                if tag_content.count('/') == 0 and tag_content.count(' ') == 0:
                    count += 1
                i = j + 1
            else:
                i += 1
        return count

    # Count all 'item' elements recursively
    def count_recursive(element):
        count = 0
        if element.tag == 'item':
            count += 1
        for child in element:
            count += count_recursive(child)
        return count

    return count_recursive(root)
