import sqlite3
from typing import Optional, Union, List, Tuple

def top_products(conn: sqlite3.Connection, limit: Union[int, str], category: Optional[str] = None) -> List[Tuple[str, float]]:
    try:
        limit = int(limit) if isinstance(limit, str) else limit
        if limit <= 0:
            raise ValueError("Limit must be a positive integer")

        query = """
        SELECT name, price
        FROM products
        WHERE (:category IS NULL OR category = :category)
        ORDER BY price DESC, name ASC
        LIMIT ?
        """

        cursor = conn.cursor()
        cursor.execute(query, {'category': category} if category is not None else {'category': None}, (limit,))
        return cursor.fetchall()

    except sqlite3.Error as e:
        raise RuntimeError(f"Database error occurred: {e}")
    except ValueError as e:
        raise ValueError(f"Invalid input: {e}")
    except Exception as e:
        raise RuntimeError(f"Unexpected error occurred: {e}")
